/*
 * A042000  Numerators of continued fraction convergents to sqrt(523).
 * https://oeis.org/A042000
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy, less
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 8, u32 n <= 17, u64 n <= 35, u128 n <= 74,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) is the numerator of the n-th convergent to √523. */
/* The convergents p_n/q_n are generated by the recurrence
   p_n = a_n * p_{n-1} + p_{n-2},
   where a_n are the partial quotients of the continued fraction of √523. */

seq_t a(idx_t n) {
    /* constants for √523 */
    const seq_t D   = (seq_t)523;   /* D in the algorithm */
    const seq_t a0  = (seq_t)22;    /* floor(√523) */

    if (n == 0) return a0;          /* first term */

    /* variables for the continued‑fraction computation */
    seq_t m = 0;                    /* m_0 */
    seq_t d = 1;                    /* d_0 */
    seq_t a = a0;                   /* a_0 */

    /* variables for the convergent recurrence */
    seq_t prev2 = 1;                /* p_{-1} */
    seq_t prev1 = a0;               /* p_0 */
    seq_t p     = 0;                /* current numerator */

    for (idx_t i = 1; i <= n; ++i) {
        /* next partial quotient a_{i} */
        m = d * a - m;
        d = (D - m * m) / d;
        a = (a0 + m) / d;

        /* convergent recurrence */
        p = a * prev1 + prev2;

        /* shift for next iteration */
        prev2 = prev1;
        prev1 = p;
    }
    return p;
}
